using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Nashi.Core;
namespace Nashi.Windows;
internal static class DesktopParityChecks
{
    private static IEnumerable<DependencyObject> Children(DependencyObject root){for(var n=0;n<VisualTreeHelper.GetChildrenCount(root);n++){var child=VisualTreeHelper.GetChild(root,n);yield return child;foreach(var inner in Children(child))yield return inner;}}
    private static T WaitFor<T>(Task<T> task){var until=DateTime.UtcNow.AddSeconds(30);while(!task.IsCompleted&&DateTime.UtcNow<until)DesktopInput.Pump(30);if(!task.IsCompleted)throw new TimeoutException("Preview fixture operation timed out.");return task.GetAwaiter().GetResult();}
    private static void WaitFor(Task task){var until=DateTime.UtcNow.AddSeconds(30);while(!task.IsCompleted&&DateTime.UtcNow<until)DesktopInput.Pump(30);if(!task.IsCompleted)throw new TimeoutException("Preview fixture operation timed out.");task.GetAwaiter().GetResult();}
    internal static void Run(string root,MainWindow owner,string image,string text,string pastedImage,Toolchain tools,Action<bool,string> check)
    {
        check(DesktopGeometry.FitsWorkArea(owner),"Home window extends beyond the display work area");
        var isolated=new LibraryStore(Path.Combine(root,"Desktop parity library"));isolated.SetAppearance(Theme.Dark?"dark":"light");var folder=Directory.CreateDirectory(Path.Combine(root,"Folder clipboard fixture")).FullName;
        var result=ClipboardImport.Read(new DataObject(DataFormats.FileDrop,new[]{folder,image,folder}),isolated);check(result.Paths.Length==2&&result.Paths.Contains(folder),"Folder paste rejected a directory or duplicated it");
        var window=new MainWindow(library:isolated,checkForUpdates:false);window.Show();DesktopInput.Pump();
        // Actual OS clipboard import, routed through native Ctrl+V, into the separate fixture Library.
        var drops=new System.Collections.Specialized.StringCollection{folder,image};Clipboard.SetFileDropList(drops);Children(window).OfType<Button>().First(b=>b.Content as string=="Home").Focus();DesktopInput.Key(window,Key.V,control:true);
        check(window.SelectedFiles.Contains(folder)&&window.SelectedFiles.Contains(image),"Native folder clipboard gesture lost selected items");
        isolated.Record("Preview batch",[text,pastedImage]);DesktopInput.Key(window,Key.F,control:true);window.SearchField.Text="Preview batch";DesktopInput.Key(window,Key.Down);
        check(!window.SearchField.IsKeyboardFocused&&window.LibraryVisible,"Down from Library search did not focus a result");
        DesktopInput.Key(window,Key.Space);var preview=Application.Current.Windows.OfType<FilePreviewWindow>().Single();DesktopInput.Pump();
        check(preview.CurrentPath==text&&Children(preview).OfType<TextBox>().Any(t=>t.Text.Contains("Türkçe")),"Library Space preview lost Unicode text");
        // The preview text is selectable; navigate from its header rather than hijacking text arrows.
        Children(preview).OfType<Button>().First().Focus();DesktopInput.Key(preview,Key.Right);DesktopInput.Pump();check(preview.CurrentPath==pastedImage&&Children(preview).OfType<Image>().Any(i=>i.Source is BitmapSource{PixelWidth:320,PixelHeight:180}),"Preview Right did not navigate to pasted image");
        var capture=new RenderTargetBitmap((int)preview.ActualWidth,(int)preview.ActualHeight,96,96,PixelFormats.Pbgra32);capture.Render(preview);ImageEngine.Save(capture,Path.Combine(root,"windows-library-preview.png"),"png");DesktopInput.Key(preview,Key.Escape);check(!preview.IsVisible,"Preview Escape did not close");
        window.Activate();DesktopInput.Pump();DesktopInput.Key(window,Key.Enter);check(window.SelectedFiles.SequenceEqual(new[]{text,pastedImage})&&!window.LibraryVisible,"Library Enter did not reuse the selected batch");window.OfferUpdate(new("99.0.0","https://github.com/orkunisitmak/nashi-app/releases/download/v99.0.0/Nashi-Windows-x64.zip",1,Convert.ToBase64String(new byte[64])));check(window.UpdateBannerVisible&&Children(window).OfType<Button>().Any(b=>b.Content as string=="Update to 99.0.0"),"A discovered update has no visible Home action");window.Close();
        var shelf=new FloatShelf([image,text],(_,_)=>Task.CompletedTask,_=>{});shelf.Show();DesktopInput.Pump();Children(shelf).OfType<ListBox>().Single().Focus();DesktopInput.Key(shelf,Key.Space);preview=Application.Current.Windows.OfType<FilePreviewWindow>().Single();DesktopInput.Pump();check(preview.CurrentPath==image,"Float Space did not use the common preview");DesktopInput.Key(preview,Key.Right);DesktopInput.Pump();check(preview.CurrentPath==text,"Float preview did not navigate its file set");DesktopInput.Key(preview,Key.Escape);shelf.Close();
        var missing=new FilePreviewWindow(owner,[Path.Combine(root,"Missing preview.txt")]);missing.Show();DesktopInput.Pump();check(Children(missing).OfType<TextBlock>().Any(t=>t.Text.Contains("moved or was removed")),"Missing preview did not recover safely");missing.Close();
        var audio=Path.Combine(root,"Keyboard preview.wav");var audioInfo=new MediaInfo(5,new FileInfo(audio).Length,[new MediaStream(0,"audio","pcm_s16le",null,null,false)]);
        preview=new FilePreviewWindow(owner,[audio,image],tools);preview.Show();DesktopInput.Pump();Children(preview).OfType<Button>().First().Focus();DesktopInput.Key(preview,Key.Right,alt:true);check(preview.CurrentPath==image,"Native Alt+Right did not leave media preview for the next file");DesktopInput.Key(preview,Key.Left,alt:true);check(preview.CurrentPath==audio,"Native Alt+Left did not return to the previous media file");DesktopInput.Key(preview,Key.Escape);
        var mediaEditor=new ToolEditor(owner,"normalizeAudio","Normalize Audio",audio,audioInfo);mediaEditor.ConfigureMediaRuntime(tools);mediaEditor.Show();DesktopInput.Pump();check(DesktopGeometry.FitsWorkArea(mediaEditor),"Media editor extends beyond the display work area");
        // Force the same FFmpeg fallback used by MediaFailed, independently of installed OS codecs.
        WaitFor(mediaEditor.CreatePreviewProxy());var playback=Children(mediaEditor).OfType<MediaElement>().Single();var proxy=playback.Source.LocalPath;
        check(proxy!=audio&&File.Exists(proxy),"Codec fallback did not create a playable source proxy");
        var normalize=Children(mediaEditor).OfType<Button>().Single(b=>b.Content as string=="Preview Processed");normalize.Focus();DesktopInput.Key(mediaEditor,Key.Space);
        var limit=DateTime.UtcNow.AddSeconds(25);while(!mediaEditor.ProcessedPlayback&&DateTime.UtcNow<limit)DesktopInput.Pump(50);
        check(mediaEditor.ProcessedPlayback&&File.Exists(mediaEditor.ProcessedPreviewPath),"Native processed audio preview did not render or activate");
        Children(mediaEditor).OfType<Button>().Single(b=>b.Content as string=="Original").Focus();DesktopInput.Key(mediaEditor,Key.Space);check(!mediaEditor.ProcessedPlayback&&playback.Source.LocalPath==proxy,"Original preview did not reuse the working codec proxy");mediaEditor.Close();
        var fineEditor=new ToolEditor(owner,"trimAudio","Trim Audio",audio,audioInfo);var observedModifiers=ModifierKeys.None;fineEditor.AddHandler(Keyboard.PreviewKeyDownEvent,new KeyEventHandler((_,e)=>{if(e.Key==Key.Right)observedModifiers=Keyboard.Modifiers;}),true);fineEditor.Show();DesktopInput.Pump();fineEditor.Timeline.Focus();var before=fineEditor.PreviewSeconds;DesktopInput.Key(fineEditor,Key.Right,shift:true);check(Math.Abs(fineEditor.PreviewSeconds-before-.1)<.06,$"Audio fine seek differs from Mac's 0.1 second step: {before} -> {fineEditor.PreviewSeconds}; active={fineEditor.IsActive}; focus={Keyboard.FocusedElement?.GetType().Name}; modifiers={observedModifiers}");fineEditor.Close();
        var clip=Path.Combine(root,"Preview 24fps.mp4");var create=ProcessRunner.RunAsync(tools.Executable("ffmpeg"),["-v","error","-f","lavfi","-i","testsrc2=size=160x90:rate=24:duration=5","-c:v","libx264","-preset","ultrafast","-pix_fmt","yuv420p",clip]);WaitFor(create);var inspect=new MediaEngine(tools.Executable("ffmpeg"),tools.Executable("ffprobe")).InspectAsync(clip);var inspected=WaitFor(inspect);
        var frameEditor=new ToolEditor(owner,"trimVideo","Trim Video",clip,inspected);frameEditor.ConfigureMediaRuntime(tools);frameEditor.Show();DesktopInput.Pump();frameEditor.Timeline.Focus();before=frameEditor.PreviewSeconds;DesktopInput.Key(frameEditor,Key.Right,shift:true);check(Math.Abs(frameEditor.PreviewSeconds-before-1d/24)<.015,"Video fine seek ignored actual 24 fps source rate");var trackWidth=frameEditor.Timeline.ActualWidth-24;DesktopInput.Drag(frameEditor.Timeline,new Point(12+trackWidth,27),new Point(12+trackWidth*.6,27));check(Math.Abs(frameEditor.PreviewSeconds-frameEditor.Timeline.End)<.1,"Dragging Out did not preview the selected end frame");frameEditor.Close();
        var fieldSubmit=new ToolEditor(owner,"resize","Resize Photo",image,preview:ImageEngine.Load(image));fieldSubmit.Dispatcher.BeginInvoke(()=>{DesktopInput.Pump();fieldSubmit.FieldForTest("Width").Focus();fieldSubmit.FieldForTest("Width").Text="123";DesktopInput.Key(fieldSubmit,Key.Enter);});check(fieldSubmit.ShowDialog()==true&&fieldSubmit.ImageOptions.Width==123,"Enter did not commit the editor field and save like Mac");
        var updatePreferences=new PreferencesStore(Path.Combine(root,"Update settings fixture"));var updateSettings=new SettingsWindow(owner,updatePreferences,()=>{},()=>Task.CompletedTask);updateSettings.Show();DesktopInput.Pump();Children(updateSettings).OfType<ListBox>().Single().SelectedItem="Updates";DesktopInput.Pump();var automatic=Children(updateSettings).OfType<CheckBox>().Single(b=>b.Content as string=="Check for updates automatically");automatic.Focus();DesktopInput.Key(updateSettings,Key.Space);check(!new PreferencesStore(Path.Combine(root,"Update settings fixture")).Value.AutomaticUpdateChecks,"Automatic update preference did not persist");check(Children(updateSettings).OfType<Button>().Any(b=>b.Content as string=="Check for updates"&&b.IsEnabled),"Turning off automatic checks disabled manual updates");updateSettings.Close();
        var labels=new[]{new ToolChoice("compress","Compress","↘"),new("metadata","Metadata","◇"),new("split","Split PDF","◫"),new("merge","Merge PDFs","▣"),new("qr","Read QR Codes","▧")};
        var wheel=new WheelWindow(owner,labels,_=>{});wheel.Show();DesktopInput.Pump();check(Math.Abs(wheel.Width-320)<.1,"Wheel default size differs from Mac");var wheelCanvas=Children(wheel).OfType<Canvas>().First();var petals=wheelCanvas.Children.OfType<System.Windows.Shapes.Path>().ToArray();var captions=wheelCanvas.Children.OfType<Button>().Take(labels.Length).ToArray();
        for(var n=0;n<labels.Length;n++){var bounds=captions[n].TransformToAncestor(wheelCanvas).TransformBounds(new Rect(0,0,captions[n].ActualWidth,captions[n].ActualHeight));check(new[]{bounds.TopLeft,bounds.TopRight,bounds.BottomLeft,bounds.BottomRight}.All(petals[n].Data.FillContains),"Multiple-PDF wheel label escaped its petal: "+labels[n].Title);}wheel.Close();
        if(Environment.GetEnvironmentVariable("GITHUB_ACTIONS")=="true")
        {
            // Hosted runners can initialize a fresh LibreOffice profile and font cache here.
            // Keep asserting a rendered page and navigation after bounded cold-start readiness.
            var runtime=new OfficeRuntime(Path.Combine(Environment.GetEnvironmentVariable("RUNNER_TEMP")!,"Nashi-Parity-Runtimes"));var docx=Path.Combine(root,"Parity exports","Office fixtures","Document.docx");var documentPreview=new FilePreviewWindow(owner,[docx],tools,runtime);documentPreview.Show();limit=DateTime.UtcNow.AddMinutes(2);while(!Children(documentPreview).OfType<Image>().Any(i=>i.Source is BitmapSource{PixelWidth:>100})&&DateTime.UtcNow<limit)DesktopInput.Pump(50);check(Children(documentPreview).OfType<Image>().Any(i=>i.Source is BitmapSource{PixelWidth:>100})&&Children(documentPreview).OfType<Button>().Any(b=>b.Content as string=="Next page"),"Office document did not open as an in-app paged preview: "+documentPreview.PreviewStatus+"; office runtime="+(runtime.Executable is null?"missing":"ready"));documentPreview.Close();check(File.Exists(docx),"Office preview changed its source document");
        }
        check(File.Exists(text)&&File.Exists(pastedImage),"Preview changed imported source files");
    }
}
